}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    font-size: 0.9rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.logo {
    font-size: 1.5rem;
    font-weight: 600;
    letter-spacing: 0.2em;
}

.nav-actions {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

/* Hero Section */
.hero {
    position: relative;
    height: 80vh;
    background-color: var(--accent);
    display: flex;
    align-items: center;
    overflow: hidden;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 600px;
}

.hero h1 {
    font-size: 4rem;
    margin-bottom: 1.5rem;
    line-height: 1.1;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-muted);
    margin-bottom: 2rem;
}

.btn {
    display: inline-block;
    padding: 1rem 2.5rem;
    background: var(--primary);
    color: var(--white);
    font-weight: 500;
    transition: var(--transition);
}

.btn:hover {
    opacity: 0.8;
}

.hero-image {
    position: absolute;
    right: 0;
    top: 0;
    width: 50%;
    height: 100%;
    background: #e0e0e0; /* Placeholder */
    object-fit: cover;
}

/* Section Common */
section {
    padding: 5rem 0;
}

.section-title {
    margin-bottom: 3rem;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
}

.section-title h2 {
    font-size: 2rem;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    position: relative;
    transition: var(--transition);
}

.product-image-wrapper {
    aspect-ratio: 3/4;
    background: #f9f9f9;
    margin-bottom: 1rem;
    overflow: hidden;
    position: relative;
}

.product-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image {
    transform: scale(1.05);
}

.badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    background: var(--primary);
    color: var(--white);
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 600;
}

.product-info h3 {
    font-size: 1rem;
    margin-bottom: 0.25rem;
}

.product-price {
    font-weight: 500;
}

.old-price {
    text-decoration: line-through;
    color: var(--text-muted);
    margin-left: 0.5rem;
    font-size: 0.9rem;
}

/* Deals Section */
.deals-section {
    background-color: var(--accent);
}

/* Editorial content */
.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial-text h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

/* Footer */
footer {
    padding: 5rem 0 2rem;
    background: #fdfdfd;
    border-top: 1px solid #eee;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 3rem;
    margin-bottom: 4rem;
}

.footer-col h4 {
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 0.1em;
}

.footer-col ul {
    list-style: none;
}

.footer-col ul li {
    margin-bottom: 0.75rem;
}

.footer-col ul a {
    color: var(--text-muted);
    font-size: 0.9rem;
    transition: var(--transition);
}

.footer-col ul a:hover {
    color: var(--primary);
}

.newsletter input {
    width: 100%;
    padding: 0.75rem;
    border: 1px solid #ddd;
    margin-bottom: 1rem;
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    padding-top: 2rem;
    border-top: 1px solid #eee;
    font-size: 0.8rem;
    color: var(--text-muted);
}

/* Accessibility */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    border: 0;
}

@media (max-width: 768px) {
    .navbar {
        padding: 0 1rem;
    }
    .nav-links {
        display: none;
    }
    .hero h1 {
        font-size: 2.5rem;
    }
    .hero-image {
        display: none;
    }
    .hero-content {
        max-width: 100%;
        text-align: center;
    }
    .editorial-grid {
        grid-template-columns: 1fr;
    }
}
